block_record <- function(block, parent, utxo, fees, source) {
    record <- new.env(parent = emptyenv())
    record$block <- block
    record$parent <- parent
    record$utxo <- utxo
    record$transaction_fees <- fees
    record$fees <- sum(fees)
    record$source <- source
    record$cumulative_work <- if (is.null(parent)) 1L else parent$cumulative_work + as.integer(16L ^ block$difficulty)
    record
}
ancestor <- function(record, height) {
    while (record$block$height > height) record <- record$parent
    record
}
chain_to <- function(record) {
    records <- list()
    while (!is.null(record)) {
        records <- c(list(record), records)
        record <- record$parent
    }
    records
}
fork_point <- function(first, second) {
    height <- min(first$block$height, second$block$height)
    first <- ancestor(first, height)
    second <- ancestor(second, height)
    while (!identical(first, second)) {
        first <- first$parent
        second <- second$parent
    }
    first
}
header_text <- function(height, previous, merkle, timestamp, difficulty, nonce) paste(
    height,
    previous,
    merkle,
    timestamp,
    difficulty,
    nonce,
    sep = "|"
)
block <- function(height, previous, merkle, timestamp, difficulty, nonce, transactions) {
    list(height = height, previous = previous, merkle = merkle, timestamp = timestamp, difficulty = difficulty, nonce = nonce, transactions = transactions,
         hash = digest(header_text(height, previous, merkle, timestamp, difficulty, nonce)))
}
block_size <- function(block) sum(vapply(block$transactions[-1L], function(tx) tx$size, 0L))
meets_difficulty <- function(hash, difficulty) startsWith(hash, paste(rep("0", difficulty), collapse = ""))
parse_block_event <- function(fields, texts) block(
    as.integer(fields[4L]),
    fields[5L],
    fields[6L],
    as.integer(fields[7L]),
    as.integer(fields[8L]),
    as.integer(fields[9L]),
    lapply(texts, parse_transaction)
)
context_free_error <- function(block, max_size) {
    if (!meets_difficulty(block$hash, block$difficulty)) return("bad-pow")
    if (merkle_root(vapply(
        block$transactions,
        function(tx) tx$txid,
        ""
    )) != block$merkle) return("bad-merkle")
    first <- block$transactions[[1L]]
    if (!is_coinbase(first) || first$coinbase_height != block$height || any(vapply(
        block$transactions[-1L],
        is_coinbase,
        FALSE
    ))) return("bad-structure")
    if (block_size(block) > max_size) return("too-large")
    NULL
}
is_coinbase <- function(tx) !is.null(tx$coinbase_height)
output_total <- function(tx) sum(vapply(tx$outputs, function(output) output$amount, 0L))
is_mature <- function(
    coin,
    height,
    maturity
) !coin$coinbase || coin$height == 0L || height >= coin$height + maturity
check_transaction <- function(tx, utxo, spent, height, owners, maturity) {
    failure <- function(reason) list(reason = reason, fee = 0L)
    for (output in tx$outputs) if (is.null(owners[[output$address]]) || output$amount == 0L) return(failure("bad-output"))
    seen <- character()
    total <- 0L
    for (i in seq_along(tx$inputs)) {
        ref <- tx$inputs[i]
        if (ref %in% spent || ref %in% seen) return(failure("double-spend"))
        coin <- utxo[[ref]]
        if (is.null(coin)) return(failure("missing-input"))
        if (!is_mature(coin, height, maturity)) return(failure("immature"))
        if (tx$signatures[i] != signature(
            owners[[coin$address]]$secret,
            i - 1L,
            transaction_body(tx)
        )) return(failure("bad-sig"))
        seen <- c(seen, ref)
        total <- total + coin$amount
    }
    if (total < output_total(tx)) return(failure("overspend"))
    list(reason = NULL, fee = total - output_total(tx))
}
apply_transaction <- function(utxo, tx, height) {
    utxo[tx$inputs] <- NULL
    for (i in seq_along(tx$outputs)) {
        output <- tx$outputs[[i]]
        utxo[[paste(tx$txid, i - 1L, sep = ":")]] <- list(
            address = output$address,
            amount = output$amount,
            height = height,
            coinbase = is_coinbase(tx)
        )
    }
    utxo
}
